Translate("esMX", "abercrombie", {
	title = "Abercrombie",
	subtitle = "El ermitaño del Cerro del Cuervo",
	found = [=[Una choza en el borde norte del Cementerio del Cerro del Cuervo]=],
	hint = [=[Visite al viejo ermitaño que vive en una choza sobre el Cementerio del Cerro del Cuervo.]=],
	allegiance = "Ninguna",
	aliases = { "El Embalsamador", "Embalsamador" },
	sections = {
		{
			title = "Resumen",
			text = [=[Abercrombie parece un anciano frágil que vive solo en una choza sobre el {link:raven-hill-cemetery}Cementerio del Cerro del Cuervo{/link}. Ya no se atreve a recorrer el camino hasta el pueblo, y pide pequeños favores a quienes pasan: hebras, bebida fuerte, huesos de necrófago para un espantapájaros, una caja que perdió a manos de los ogros. Es agradecido y se ríe mucho. También es el Embalsamador.]=],
		},
		{
			title = "Importancia",
			text = [=[Los niños de {link:darkshire}Villa Oscura{/link} conocen al Embalsamador por un cuento para dormir. Era un alquimista bondadoso, y cuando murió su esposa {link:eliza}Eliza{/link}, el dolor lo volvió loco. Colocó su propio corazón en el pecho de ella para traerla de vuelta. Ella se alzó de nuevo con hambre de carne humana, y él tuvo que mantenerla enterrada. La historia es cierta, y el Embalsamador vive junto a su tumba.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reunió hebra de pelo de fantasma, jugo de zombi y costillas de necrófago por medio de manos desconocidas.
• Construyó una criatura de carne, hueso y metal para enviarla contra {link:darkshire}Villa Oscura{/link}.
• Escribió al alcalde en una escritura que nadie en el pueblo sabía leer.]=],
		},
		{
			title = "Sin registro",
			text = [=[El verdadero nombre del ermitaño, su edad y los años de su locura no están escritos en ninguna parte.]=],
		},
	},
	chapters = {
		{
			title = "Los favores de un anciano",
			hint = [=[Ayude al ermitaño con las cosas que no puede ir a buscar él mismo.]=],
			text = [=[La hebra, dijo, era para sus puertas y ventanas, para mantener alejados a los espíritus. El jugo era para calentarse en las noches frías. Las costillas eran para un espantapájaros contra los necrófagos. Cada cosa era inofensiva por sí sola. Todas fueron a parar a la misma obra.]=],
		},
		{
			title = "La criatura a la puerta",
			hint = "Descubra lo que dice en verdad la carta del ermitaño.",
			text = [=[Una vez traducida, la carta era una fanfarronada. Abercrombie se llamaba a sí mismo creador. Su obra más reciente aguardaba fuera de su choza, rechinando los dientes, lista para marchar sobre {link:darkshire}Villa Oscura{/link} a su orden. El desconocido que lo había ayudado la había construido sin saberlo.]=],
		},
	},
	mentions = {
		{ text = "El ermitaño" },
		{ text = "Entregar la hebra" },
		{ text = "Entrega de jugo" },
		{ text = "Efigie macabra" },
		{ text = "Ladrones ogros" },
		{ text = "Nota para el alcalde" },
	},
	bonds = {
		{ id = "eliza", name = "Eliza", note = "su esposa" },
		{ id = "stitches", name = "Stitches", note = "su creación" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "leyó su carta" },
		{ id = "madame-eva", name = "Madame Eva", note = "hizo su hebra" },
	},
})

Translate("esMX", "eliza", {
