	chapters = {
		{
			title = "La tumba abierta",
			hint = "Cave en la tumba cercana a la choza del ermitaño.",
			text = [=[La tierra sobre la tumba estaba suelta, como si la hubieran cavado y rellenado más de una vez. Debajo había un ataúd, y de dentro llegaba el roce de unas garras y el rechinar de unos dientes podridos. Cuando se abrió la tapa, Eliza salió. Le arrancaron el corazón todavía latiendo. El alcalde de {link:darkshire}Villa Oscura{/link} lo llamó prueba contra el mal del loco, y juró que el nombre de quien lo llevó quedaría para siempre en los anales del pueblo.]=],
		},
