	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "su marido" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "mandó buscar el corazón de su marido" },
	},
})

Translate("esMX", "stalvan-mistmantle", {
	title = "Stalvan Mistmantle",
	subtitle = "El preceptor de la Mansión Mantoniebla",
	found = "Mansión Mantoniebla, al norte de Villa Oscura",
	hint = "Busque la casa solitaria al norte de Villa Oscura.",
	allegiance = "Ninguna",
	aliases = { "Stalvan" },
	sections = {
		{
			title = "Resumen",
			text = [=[Stalvan Mistmantle vino del {link:silverpine-forest}Bosque de Argénteos{/link} y estudió con el director Crillian en una academia de {link:stormwind-city}Ventormenta{/link}. Se hizo maestro de niños, primero en {link:moonbrook}Arroyo de la Luna{/link} y luego en la casa de una familia noble, los Flintridge. Allí se enamoró de su alumna Tilloa. Cuando ella eligió a otro, su amor se convirtió en odio. Siguió una masacre en la casa de los Flintridge, y Stalvan acabó viviendo solo en los bosques sobre {link:darkshire}Villa Oscura{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Stalvan es la leyenda más oscura de {link:duskwood}Bosque del Ocaso{/link}. La verdad sobre él permaneció oculta durante años en páginas dispersas, una carta perdida y el recuerdo de un viejo mariscal de {link:stormwind-city}Ventormenta{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió la nueva escuela de {link:moonbrook}Arroyo de la Luna{/link} y la dejó cuando llegaron los problemas a {link:westfall}Páramos de Poniente{/link}.
• Se convirtió en preceptor de Giles y Tilloa, los hijos de la familia Flintridge.
• Llevó un diario que recogía su amor por Tilloa y su descenso a la ira.]=],
		},
	},
	chapters = {
		{
			title = "El rastro de las cartas",
			hint = [=[Siga el nombre de Stalvan desde Villa Oscura hasta Arroyo de la Luna y Villadorada.]=],
			text = [=[El registro del pueblo guardaba dos direcciones de Stalvan. En {link:moonbrook}Arroyo de la Luna{/link}, una carta que nunca envió hablaba de su alegría por construir una escuela. En la posada Lion's Pride de {link:goldshire}Villadorada{/link} aguardaba otra, olvidada por un mensajero que huyó una noche de tormenta. En ella, Stalvan ofrecía sus servicios como preceptor a una casa noble.]=],
		},
		{
			title = "El diario",
			hint = "Reúna las páginas dispersas del diario de Stalvan.",
			text = [=[Las páginas cuentan la historia de su puño y letra. Escribió sobre la belleza de Tilloa, sobre una flor que ella le puso en la palma, sobre un verano en la casa de campo de la familia cerca de {link:stranglethorn-vale}la Vega{/link} del Este. Luego escribió sobre la furia, cuando ella lo llamó un viejo simpático delante de su pretendiente, y sobre un vacío negro que crecía en su interior. La última página promete sangre.]=],
		},
		{
			title = "La ejecución",
			hint = "Cumpla la sentencia de la Guardia Nocturna.",
			text = [=[Cuando el escribano de {link:darkshire}Villa Oscura{/link} comparó la letra del diario con la del registro, la {link:the-night-watch}Guardia Nocturna{/link} tuvo su prueba. Stalvan murió en su casa, y el anillo de su familia fue llevado a la vidente que lo había nombrado por primera vez. Ella sintió que el bosque respiraba más tranquilo.]=],
		},
	},
	mentions = {
		{ text = "La leyenda de Stalvan" },
		{ text = "La leyenda de Stalvan" },
		{ text = "La leyenda de Stalvan" },
		{ text = "La leyenda de Stalvan" },
	},
	bonds = {
		{ id = "marshal-haggard", name = "Mariscal Haggard", note = "investigó la masacre" },
		{ id = "madame-eva", name = "Madame Eva", note = "vio su nombre en una visión" },
		{ id = "commander-althea-ebonlocke", name = "Comandante Althea Ebonlocke", note = "ordenó su muerte" },
		{ id = "clerk-daltry", name = "Escribano Daltry", note = "identificó su letra" },
	},
})

Translate("esMX", "mor-ladim", {
	title = "Mor'Ladim",
	subtitle = "El caballero sin descanso",
	found = "Vagando por el Cementerio del Cerro del Cuervo",
	hint = [=[Enfréntese al caballero muerto que vaga por el Cementerio del Cerro del Cuervo.]=],
	allegiance = "Ninguna",
	aliases = { "Morgan Ladimore" },
	sections = {
		{
			title = "Resumen",
			text = [=[Morgan Ladimore fue un caballero que luchó por los inocentes y los pobres. Se casó con una muchacha llamada Lys cuando tenía dieciocho años, y tuvieron un hijo y dos hijas. Cuando la guerra llegó a {link:lordaeron}Lordaeron{/link}, marchó al norte para luchar al lado de {link:uther-the-lightbringer}Uther el Iluminado{/link}. Al volver a casa encontró su bosque podrido y su casa en ruinas. Ahora recorre el cementerio como Mor'Ladim, un ser muerto que mata sin razón.]=],
		},
		{
			title = "Importancia",
			text = [=[La caída de {link:morgan-stern}Morgan{/link} es la historia más triste de {link:duskwood}Bosque del Ocaso{/link}. Era un buen hombre destrozado por el dolor. Su nombre es una advertencia de lo que la oscuridad del bosque puede hacer incluso al corazón más fuerte.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Sirvió a {link:uther-the-lightbringer}Uther{/link} durante la guerra del norte y vio disolverse la orden de los paladines, morir a Uther y extenderse la peste.
• Buscó a su familia en cada granja y cada casa de {link:duskwood}Bosque del Ocaso{/link}.
• En el {link:raven-hill-cemetery}Cementerio del Cerro del Cuervo{/link} encontró una lápida con el nombre de su esposa.
• En su dolor mató a tres cuidadores del cementerio y después se quitó la vida.]=],
		},
	},
	chapters = {
		{
			title = "La tumba desgastada",
			hint = [=[Busque una tumba en el extremo del Cementerio del Cerro del Cuervo.]=],
			text = [=[Fue enterrado deprisa, sin ritos, más allá del borde del cementerio. Días después la tierra había sido removida, y la tumba estaba vacía. El historiador de {link:darkshire}Villa Oscura{/link}, que había conocido a {link:morgan-stern}Morgan{/link} antes de la guerra, guarda un libro que cuenta su historia.]=],
		},
		{
			title = "El anillo de una hija",
			hint = "Lleve consuelo a la tumba de Morgan Ladimore.",
			text = [=[{link:morgan-stern}Morgan{/link} murió creyendo muerta a toda su familia. Una hija, Sarah, había sobrevivido. Cuando se depositó su anillo sobre la tumba de él, una voz se alzó en el viento. El caballero pronunció maravillado el nombre de su hija, y el peso que cargaba su alma se levantó. Entregó su espada Archeus a quien le había traído la paz, y sus últimas palabras fueron para su esposa, Lys.]=],
		},
	},
	mentions = {
		{ text = "La tumba desgastada" },
		{ text = "Morgan Ladimore" },
		{ text = "Mor'Ladim" },
		{ text = "El amor de una hija" },
	},
	bonds = {
		{ id = "sarah-ladimore", name = "Sarah Ladimore", note = "su hija" },
		{ id = "sirra-von-indi", name = "Sirra Von'Indi", note = "lo conoció antes de la guerra" },
		{ id = "commander-althea-ebonlocke", name = "Comandante Althea Ebonlocke", note = "le dio caza" },
		{ id = "uther-the-lightbringer", name = "Uther el Iluminado", note = "el paladín al que sirvió" },
	},
})

Translate("esMX", "sven-yorgen", {
