})

Translate("esMX", "stitches", {
	title = "Stitches",
	subtitle = "Regalo del Embalsamador",
	found = "El camino del Cerro del Cuervo a Villa Oscura",
	hint = [=[Tenga cuidado con la criatura que marcha por el camino hacia Villa Oscura.]=],
	allegiance = "El Embalsamador",
	sections = {
		{
			title = "Resumen",
			text = [=[Stitches es la criatura del {link:abercrombie}Embalsamador{/link}, hecha de carne, hueso y metal retorcido. Fue construida con las mismas cosas que un desconocido llevó a la choza del ermitaño, y aguardó fuera de esa choza la orden de su amo. Cuando llegó la orden, marchó por el camino hacia {link:darkshire}Villa Oscura{/link} para masacrar todo lo que encontrara.]=],
		},
		{
			title = "Importancia",
			text = [=[Stitches es la prueba de que el viejo cuento infantil del {link:abercrombie}Embalsamador{/link} era cierto, y de que el loco no había dejado de fabricar cosas.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Aguardó fuera de la choza del ermitaño la orden de su creador.
• Partió hacia {link:darkshire}Villa Oscura{/link} poco después de que se tradujera la carta del {link:abercrombie}Embalsamador{/link}.]=],
		},
	},
	mentions = {
		{ text = "Traducción para Ello" },
	},
	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "su creador" },
	},
})

Translate("esMX", "avette-fellwood", {
	title = "Avette Fellwood",
	subtitle = "Fabricante de arcos de Villa Oscura",
	found = "Villa Oscura, en su puesto de arcos",
	hint = [=[Busque a la fabricante de arcos de Villa Oscura que ha acogido a un niño huérfano.]=],
	allegiance = "Villa Oscura",
	aliases = { "Avette" },
	sections = {
		{
			title = "Resumen",
			text = [=[Avette Fellwood es una fabricante de arcos de {link:darkshire}Villa Oscura{/link}. Hace poco adoptó a Jeremy Heartweaver, un niño que sobrevivió a la caída de {link:lordaeron}Lordaeron{/link} y fue llevado a un orfanato de {link:stormwind-city}Ventormenta{/link}. Jeremy no ha hablado desde el ataque a su ciudad. Su padre, Edward, se alzó entre los {link:forsaken}Renegados{/link} y buscaba cada semana el cuerpo de su hijo en las ruinas de la capital, hasta que un día no regresó. Su última carta, manchada de sangre, ha llegado a manos de Avette.]=],
		},
		{
			title = "Importancia",
			text = [=[Avette eligió proteger al niño en lugar de herirlo. No le ocultará su pasado. Le dará la carta de su padre cuando tenga edad suficiente para soportarla.]=],
		},
	},
	mentions = {
		{ text = "Recuerda que te quiero" },
	},
	bonds = {
		{ id = "ruins-of-lordaeron", name = "Ruinas de Lordaeron", note = "donde se encontró la carta" },
	},
})

Translate("esMX", "the-night-watch", {
	title = "La Guardia Nocturna",
	aliases = { "Guardia Nocturna", "vigías" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Guardia Nocturna es la milicia de {link:darkshire}Villa Oscura{/link}. Se alzó cuando una magia inmunda se filtró en {link:duskwood}Bosque del Ocaso{/link} y {link:stormwind-city}Ventormenta{/link} llamó a sus guardias de vuelta a casa. Desde entonces, la Guardia ha sido lo único que se interpone entre el pueblo y el bosque. La dirige la comandante {link:commander-althea-ebonlocke}Althea Ebonlocke{/link}, y sus miembros reciben el nombre de vigías.]=],
		},
		{
			title = "Los vigías",
			text = [=[Los vigías guardan las puertas y la plaza de {link:darkshire}Villa Oscura{/link}, y unos pocos ocupan puestos solitarios en los caminos: dos en el camino del oeste y uno en el camino del norte, junto a un comerciante goblin. Son demasiado pocos, y lo saben. Su comandante no puede enviarlos lejos del pueblo. Cuando los muertos se alzan en los cementerios, debe pedir a desconocidos que vayan en su lugar. El caballero muerto {link:mor-ladim}Mor'Ladim{/link} ha matado a algunos de los más fuertes.]=],
		},
		{
			title = "La Guardia y el mundo",
			text = [=[{link:darkshire}Villa Oscura{/link} ha llegado a depender de la Guardia como su único ejército. Cuando el magistrado {link:magistrate-solomon}Solomon{/link} de {link:lakeshire}Villa del Lago{/link} se la suplicó a {link:lord-ello-ebonlocke}lord Ebonlocke{/link}, el alcalde se negó: si la Guardia partía, el pueblo caería antes de que llegara al linde del bosque. No todos la admiran. El cazador {link:calor}Calor{/link} dejó la Guardia por {link:carevin-family}la familia Carevin{/link} y la llamó complaciente. Entre los vigías están {link:sarah-ladimore}Sarah Ladimore{/link}, hija de un caballero caído, y, en las historias del {link:raven-hill}Cerro del Cuervo{/link}, el arquero Merrick Valor.]=],
		},
	},
})

Translate("esMX", "nightbane-worgen", {
	title = "Huargen Nightbane",
	aliases = { "Nightbane", "ferocanis Nightbane" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Nightbane son los {red:worgen}ferocanis{/red} de {link:duskwood}Bosque del Ocaso{/link}: grandes hombres lobo que cazan en manadas por la mitad sur del bosque. Tejedores de sombras y corredores oscuros recorren la {link:brightwood-grove}Arboleda del Destello{/link} y {link:the-rotting-orchard}El Vergel Pútrido{/link}. Los más fuertes, los colmillos viles y los corrompidos, mantienen sus hogueras cerca de las cuevas del sur y en la mina de la {link:roland-s-doom}Condena de Roland{/link}.]=],
		},
		{
			title = "Su llegada",
			text = [=[Los ferocanis no siempre estuvieron aquí. Los cazadores de {link:darkshire}Villa Oscura{/link} dicen que aparecieron como salidos de la nada, y los primeros se encontraron en la {link:roland-s-doom}Condena de Roland{/link}. Un minero de esa mina, el hombre al que llaman {link:jitters}Jitters{/link}, cuenta cómo sucedió. Encontró el mango de una guadaña en un montón de escombros y tiró de él. Esa noche los ferocanis salieron de cada agujero y cada saliente de los túneles, y la mayoría de los mineros murió. Perdió la guadaña en su huida. No sabe si fue él quien trajo a los hombres lobo a {link:duskwood}Bosque del Ocaso{/link}, pero lo teme.

La guadaña era la {red:scythe-of-elune}Guadaña de Elune{/red}. Una sacerdotisa elfa de la noche, Velinde Starsong, la había llevado a estos bosques, y su destino se conoció en las minas. A las centinelas de {link:darnassus}Darnassus{/link} les inquietaba que un regalo de su diosa hubiera salido de las manos de sus siervas.]=],
		},
		{
			title = "La guerra contra ellos",
			text = [=[La familia Carevin y su cazador {link:calor}Calor{/link} libran una guerra sin fin contra los Nightbane. Cada manada que destruyen es pronto reemplazada. Nadie en {link:darkshire}Villa Oscura{/link} sabe todavía qué poder los atrae.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días explica cómo la Guadaña llamó a los ferocanis, ni si los Nightbane están emparentados con los ferocanis del {link:silverpine-forest}Bosque de Argénteos{/link}.]=],
		},
	},
})

Translate("esMX", "the-valor-family", {
	title = "La familia Valor",
	aliases = { "familia Valor" },
	sections = {
		{
			title = "Resumen",
			text = [=[La familia Valor fue la defensora del {link:raven-hill}Cerro del Cuervo{/link} antes de su caída. Un tomo hallado en la aldea en ruinas, {i}Recuerdos de Valor{/i}, los recoge uno por uno. Su autor llora por ellos y se culpa de su ausencia.]=],
		},
		{
			title = "La familia",
			text = [=[• {b}Lord Grant Valor.{/b} El cabeza de la familia y el líder del {link:raven-hill}Cerro del Cuervo{/link}. Cuando la oscuridad entró en los bosques, fue el primero en reunir a los aldeanos. Odiaba a los no-muertos por encima de todos los enemigos y patrullaba él mismo los cementerios. Una grave herida que ellos le causaron nunca llegó a sanar del todo.
• {b}Lady Cassandra Valor.{/b} Su esposa. Poco se sabe de ella, aparte de su amor por su familia.
• {b}Silvia Valor.{/b} Una guardia del Cerro del Cuervo, famosa por pasar a cuchillo a bandidos y estafadores. Se dice que nunca abandonó las granjas de {link:duskwood}Bosque del Ocaso{/link}.
• {b}Ira Valor.{/b} Cuando su padre cayó enfermo, se adentró en el bosque para reunir comida, y llegó a preferir el bosque oscuro a la aldea. Los viajeros perdidos hablan de una sombra que los guía de vuelta al camino.
• {b}Merrick Valor.{/b} El hijo menor. Se unió a la {link:the-night-watch}Guardia Nocturna{/link} y vigilaba los caminos con su arco.]=],
		},
		{
			title = "Sus fantasmas",
			text = [=[Los Valor desaparecieron todos a la vez. Ahora sus espíritus recorren el bosque, todavía entregados a la tarea que tenían en vida: Grant entre los esqueletos del cementerio, Silvia cerca de las granjas, Ira en el bosque, Merrick en los caminos. {link:sirra-von-indi}Sirra Von'Indi{/link}, el historiador de {link:darkshire}Villa Oscura{/link}, cree que algún dolor compartido los ata a este mundo.]=],
		},
		{
			title = "Sin registro",
			text = [=[Todavía no se sabe qué les ocurrió a los Valor, ni qué retiene a sus espíritus.]=],
		},
	},
})

Translate("esMX", "carevin-family", {
	title = "Familia Carevin",
	aliases = { "los Carevin", "la familia Carevin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Carevin son una casa de {link:darkshire}Villa Oscura{/link} que ha emprendido una guerra propia. Cazan demonios, no-muertos y a todos los que les prestan ayuda, y no confían en nadie que no quiera ayudar a su causa. Su cabeza es {link:jonathan-carevin}Jonathan Carevin{/link}. Su cazador {link:calor}Calor{/link}, antiguo miembro de la {link:the-night-watch}Guardia Nocturna{/link}, dirige la lucha contra los {link:nightbane-worgen}ferocanis Nightbane{/link}.]=],
		},
		{
			title = "La casa",
			text = [=[Elaine Carevin se ocupa de las necesidades de los marginados del pueblo. Envía provisiones a {link:sven-yorgen}Sven Yorgen{/link}, en el oeste, a quien llama un hombre que hace la obra de la Luz, y le preocupa el viejo ermitaño que ya no viene al mercado. Scott Carevin vende setas en la plaza, y un niño pequeño, Benjamin, juega cerca de la casa.]=],
		},
		{
			title = "Los Carevin y la Guardia",
			text = [=[Los Carevin no se oponen abiertamente a la {link:the-night-watch}Guardia Nocturna{/link}. Sin embargo, {link:calor}Calor{/link} no oculta su desprecio por ella. Sueña con el día en que los seguidores de los Carevin superen en número a los vigías.]=],
		},
	},
})
